/// <summary>
/// Bug 306156: [MS] CB201 - Customer rebates: Attribute Filtering Logic Not Correct - MS SR # 2410100030001214
/// </summary>
final class METTAMRebateQueryBuilderORAttributesFacade
{
    Query           query;
    TAMRebateTable  rebateTable;
    TAMRebateQueryBuilder rebateQueryBuilder;

}

Method.Source:
/// <summary>
/// Construct
/// </summary>
/// <param name = "_rebateQueryBuilder"><c>TAMRebateQueryBuilder</c></param>
/// <param name = "_rebateTable"><c>TAMRebateTable</c></param>
/// <param name = "_query"><c>Query</c></param>
/// <returns><c>METTAMRebateQueryBuilderORAttributesFacade</c></returns>
public static METTAMRebateQueryBuilderORAttributesFacade construct(TAMRebateQueryBuilder _rebateQueryBuilder, TAMRebateTable _rebateTable, Query _query)
{        
    METTAMRebateQueryBuilderORAttributesFacade ret = new METTAMRebateQueryBuilderORAttributesFacade();
    ret.rebateQueryBuilder = _rebateQueryBuilder;
    ret.query = _query;
    ret.rebateTable = _rebateTable;

    return ret;
}

/// <summary>
/// Run the OR attributes filtering logic
/// </summary>
/// <returns>Updated <c>Query</c> object</returns>
public Query run()
{
    boolean queryRangesAdded = false;
    TAMRebateDeal rebateDeal = rebateTable.TAMRebateDeal();

    if (GUPGlobalEnableFeatureHelper::isPricingRuleHashFeatureEnabled()
    &&  rebateTable.RebateAgreementType
    // When set to True- the custom OR filter logic should apply only for customer rebates.
    && TAMRebateParameters::find().METUseOrAttributes
    // Only for customer rebates
    && rebateDeal.ModuleInventCustVend == ModuleInventCustVend::Cust
    // Customer rebates only with Rebate type standard
    && rebateDeal.RebateTypeGUP == TAMRebateTypeGUP::Standard
    // and rebate output Financial
    && rebateDeal.RebateOutputType == TAMRebateOutputType::Financial)
    {
        // Run for header attributes
        METTAMRebateQueryBuilderORAttributes orAttributes;
        orAttributes = METTAMRebateQueryBuilderORAttributes::construct(HeaderLines_IT::Header, rebateQueryBuilder, rebateTable, query);
        query = orAttributes.run();
        queryRangesAdded = orAttributes.hasQueryRangesAdded();

        // Run for line attributes
        orAttributes = METTAMRebateQueryBuilderORAttributes::construct(HeaderLines_IT::Lines, rebateQueryBuilder, rebateTable, query);
        query = orAttributes.run();
        queryRangesAdded = queryRangesAdded || orAttributes.hasQueryRangesAdded();
    }

    // If there is at least one OR and queryRanges added to the query
    // need to add the group by to handle the one 2 many join for product/customer attributes
    if (queryRangesAdded)
    {
        this.addOrAttributesGroupBy();
    }

    return query;
}

/// <summary>
/// Group by for OR attribute filtering to eliminate duplicates with product/customer attributes e.g. product = item1 OR brand = brand1
/// </summary>
private void addOrAttributesGroupBy()
{
    QueryBuildDataSource qbdsHeader = query.dataSourceTable(rebateQueryBuilder.journalTable());

    // GROUP BY
    if (qbdsHeader.table() == tableNum(SalesTable))
    {
        qbdsHeader.orderMode(OrderMode::GroupBy);
        qbdsHeader.addGroupByField(fieldNum(SalesTable, InvoiceAccount));
        qbdsHeader.addGroupByField(fieldNum(SalesTable, CashDisc));
        qbdsHeader.addGroupByField(fieldNum(SalesTable, DataAreaId));
        qbdsHeader.addGroupByField(fieldNum(SalesTable, InclTax));
    }
    else if (qbdsHeader.table() == tableNum(CustPackingSlipJour))
    {
        qbdsHeader.orderMode(OrderMode::GroupBy);
        qbdsHeader.addGroupByField(fieldNum(CustPackingSlipJour, InvoiceAccount));
    }
    else if (qbdsHeader.table() == tableNum(CustInvoiceJour))
    {
        qbdsHeader.orderMode(OrderMode::GroupBy);
        qbdsHeader.addGroupByField(fieldNum(CustInvoiceJour, InvoiceAccount));
        qbdsHeader.addGroupByField(fieldNum(CustInvoiceJour, CashDiscCode));
        qbdsHeader.addGroupByField(fieldNum(CustInvoiceJour, SalesId));
        qbdsHeader.addGroupByField(fieldNum(CustInvoiceJour, CurrencyCode));
        qbdsHeader.addGroupByField(fieldNum(CustInvoiceJour, InvoiceId));
        qbdsHeader.addGroupByField(fieldNum(CustInvoiceJour, InvoiceDate));
        qbdsHeader.addGroupByField(fieldNum(CustInvoiceJour, LedgerVoucher));
        qbdsHeader.addGroupByField(fieldNum(CustInvoiceJour, RefNum));
        qbdsHeader.addGroupByField(fieldNum(CustInvoiceJour, DocumentNum));
    }

    QueryBuildDataSource qbdsLine = query.dataSourceTable(rebateQueryBuilder.transTable());
    // Add group by SalesLine
    if (qbdsLine.table() == tableNum(SalesLine))
    {
        qbdsLine.orderMode(OrderMode::GroupBy);
        qbdsLine.addGroupByField(fieldNum(SalesLine, CreatedDateTime));
        qbdsLine.addGroupByField(fieldNum(SalesLine, InventTransId));
        qbdsLine.addGroupByField(fieldNum(SalesLine, ItemId));
        qbdsLine.addGroupByField(fieldNum(SalesLine, InventDimId));
        qbdsLine.addGroupByField(fieldNum(SalesLine, RecId));
        qbdsLine.addGroupByField(fieldNum(SalesLine, TaxGroup));
        qbdsLine.addGroupByField(fieldNum(SalesLine, TaxItemGroup));
        qbdsLine.addGroupByField(fieldNum(SalesLine, InventTransIdReturn));
        qbdsLine.addGroupByField(fieldNum(SalesLine, SalesId));
        qbdsLine.addGroupByField(fieldNum(SalesLine, CurrencyCode));
        qbdsLine.addGroupByField(fieldNum(SalesLine, PdsCWQty));
        qbdsLine.addGroupByField(fieldNum(SalesLine, SalesQty));
        qbdsLine.addGroupByField(fieldNum(SalesLine, DefaultDimension));
        qbdsLine.addGroupByField(fieldNum(SalesLine, SalesUnit));
        qbdsLine.addGroupByField(fieldNum(SalesLine, TAMRebateExcludeRebateManagement));
        qbdsLine.addGroupByField(fieldNum(SalesLine, LineAmount));
        qbdsLine.addGroupByField(fieldNum(SalesLine, RetailVariantId));
        qbdsLine.addGroupByField(fieldNum(SalesLine, TAMRebateTransId));

        // all fields from SalesPurchLine
        qbdsLine.addGroupByField(fieldNum(SalesLine, SalesPrice));
        qbdsLine.addGroupByField(fieldNum(SalesLine, PriceUnit));
        qbdsLine.addGroupByField(fieldNum(SalesLine, SalesMarkup));

    }
    else if (qbdsLine.table() == tableNum(CustPackingSlipTrans))
    {
        qbdsLine.orderMode(OrderMode::GroupBy);
        qbdsLine.addGroupByField(fieldNum(CustPackingSlipTrans, CreatedDateTime));
        qbdsLine.addGroupByField(fieldNum(CustPackingSlipTrans, InventTransId));
        qbdsLine.addGroupByField(fieldNum(CustPackingSlipTrans, ItemId));
        qbdsLine.addGroupByField(fieldNum(CustPackingSlipTrans, InventDimId));
        qbdsLine.addGroupByField(fieldNum(CustPackingSlipTrans, RecId));
        qbdsLine.addGroupByField(fieldNum(CustPackingSlipTrans, PackingSlipId));
        qbdsLine.addGroupByField(fieldNum(CustPackingSlipTrans, CurrencyCode));
        qbdsLine.addGroupByField(fieldNum(CustPackingSlipTrans, PdsCWQty));
        qbdsLine.addGroupByField(fieldNum(CustPackingSlipTrans, Qty));
        qbdsLine.addGroupByField(fieldNum(CustPackingSlipTrans, DefaultDimension));
        qbdsLine.addGroupByField(fieldNum(CustPackingSlipTrans, SalesUnit));

        qbdsLine.addGroupByField(fieldNum(CustPackingSlipTrans, PriceUnit));
        qbdsLine.addGroupByField(fieldNum(CustPackingSlipTrans, DeliveryDate));
        // Very important for Attribute matching in GUPRebateMatchingHelper\checkIfPricingAttributesAreMatched to retrieve the salesTable record
        qbdsLine.addGroupByField(fieldNum(CustPackingSlipTrans, SalesId));
    }
    else if (qbdsLine.table() == tableNum(CustInvoiceTrans))
    {
        qbdsLine.orderMode(OrderMode::GroupBy);
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, CreatedDateTime));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, InventTransId));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, ItemId));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, InventDimId));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, RecId));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, TaxGroup));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, TaxItemGroup));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, CurrencyCode));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, PdsCWQty));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, Qty));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, InventQty));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, DefaultDimension));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, SalesUnit));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, LineAmount));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, SumLineDisc));

        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, PriceUnit));

        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, ParentRecId));
        // Very important for Attribute matching in GUPRebateMatchingHelper\checkIfPricingAttributesAreMatched to retrieve the salesTable record
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, SalesId));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, InvoiceId));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, InvoiceDate));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, NumberSequenceGroup));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, DataAreaId));
    }
}
